changeSet.sql:
CREATE TABLE guidance_document (
    id uuid PRIMARY KEY,
    doc_number varchar(100) NOT NULL,
    issuing_authority varchar(300) NOT NULL,
    issued_on date NOT NULL,
    title varchar(1000) NOT NULL,
    received_on date,
    field varchar(200) NOT NULL DEFAULT '',
    summary varchar(4000) NOT NULL DEFAULT '',
    notes varchar(2000) NOT NULL DEFAULT '',
    version bigint NOT NULL DEFAULT 0,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by varchar(255) NOT NULL,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by varchar(255) NOT NULL,
    CONSTRAINT ck_guidance_received CHECK (received_on IS NULL OR received_on >= issued_on)
);
CREATE UNIQUE INDEX ux_guidance_number ON guidance_document (lower(doc_number), lower(issuing_authority), issued_on);
CREATE INDEX ix_guidance_issued ON guidance_document (issued_on DESC);
ALTER TABLE attachment ALTER COLUMN hamlet_id DROP NOT NULL;
ALTER TABLE attachment DROP CONSTRAINT attachment_owner_kind_check;
ALTER TABLE attachment ADD CONSTRAINT attachment_owner_kind_check CHECK (owner_kind IN ('RESIDENT','FACILITY','GUIDANCE'));

DO $$ BEGIN
            IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='police_runtime') THEN
                GRANT SELECT,INSERT,UPDATE,DELETE ON guidance_document TO police_runtime;
            END IF;
        END $$;

rollback.sql:
